import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture as textureNode } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load ceramic grain texture
  const texture = ctx.textureLoader.load(config.assets?.imageUrl || '/prism-assets/chrome/ceramic-grain.map.png');
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create plane geometry with 512:320 aspect ratio
  const aspectRatio = 512 / 320;
  const planeWidth = 1.0;
  const planeHeight = planeWidth / aspectRatio;
  const planeGeometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // TSL material with textured surface
  const planeMaterial = new MeshBasicNodeMaterial({
    colorNode: textureNode(texture)
  });

  const planeMesh = new THREE.Mesh(planeGeometry, planeMaterial);
  group.add(planeMesh);

  // Extract text content
  const textContent = config.textContent || { text: "Features 3" };
  const textString = typeof textContent === 'string' ? textContent : (textContent.text || "Features 3");

  // Create text mesh via fontAtlas
  const textMesh = ctx.fontAtlas.createMesh(textString, {
    size: 0.34, // headline em size
    font: 'Lora',
    weight: 400,
    color: new THREE.Color(0x16161d) // ink
  });

  // Position text on top of background
  if (textMesh) {
    if (textMesh.geometry && typeof textMesh.geometry.center === 'function') {
      textMesh.geometry.center();
    }
    textMesh.position.z = 0.05;
    group.add(textMesh);
  }

  // Apply scene placement
  group.position.set(3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Event handlers (empty for static element)
  group.userData.handlers = {};

  // Cleanup function
  group.userData.cleanup = () => {
    planeGeometry.dispose();
    planeMaterial.dispose();
    texture.dispose();

    if (textMesh) {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) textMesh.material.dispose();
      if (Array.isArray(textMesh.children)) {
        textMesh.children.forEach(child => {
          if (child.geometry) child.geometry.dispose();
          if (child.material) child.material.dispose();
        });
      }
    }

    gsap.killTweensOf(group);
  };

  return group;
}
